TLM.f("Sancti/11-22",{"officium":"S. Cæciliæ Virginis et Martyris","rule":["vide C6;","Gloria"],"ruleInherited":["Gloria"],"fallback":"Commune/C6","from":{"GradualeP":"Commune/C6","Tractus":"Commune/C6"},"sections":{"Introitus":[{"k":"ref","la":"Ps 118:46-47"},{"k":"text","la":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui nos ánnua beátæ Cæcíliæ Vírginis et Mártyris tuæ sollemnitáte lætíficas: da, ut, quam venerámur offício, étiam piæ conversatiónis sequámur exémplo."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 51:13-17"},{"k":"text","la":"Dómine, Deus meus, exaltásti super terram habitatiónem meam, et pro morte defluénte deprecáta sum. Invocávi Dóminum, Patrem Dómini mei, ut non derelínquat me in die tribulatiónis meæ, et in témpore superbórum sine adjutório. Laudábo nomen tuum assídue, et collaudábo illud in confessióne, et exaudíta est orátio mea. Et liberásti me de perditióne, et eripuísti me de témpore iníquo. Proptérea confitébor et laudem dicam tibi, Dómine, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 44:11; 44:12"},{"k":"text","la":"Audi, fília, et vide, et inclína aurem tuam: quia concupívit Rex spéciem tuam. V.Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 25:4; 25:6"},{"k":"text","la":"Quinque prudéntes vírgines accepérunt óleum in vasis suis cum lampádibus: média autem nocte clamor factus est: Ecce, sponsus venit: exíte óbviam Christo Dómino. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 44:8"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem."},{"k":"text","la":"Proptérea unxit te Deus, Deus tuus, óleo lætítiæ.","mark":"V"},{"k":"text","la":"Veni, Sponsa Christi, áccipe corónam, quam tibi Dóminus præparávit in ætérnum: pro cujus amóre sánguinem tuum fudísti."},{"k":"ref","la":"Ps 44:8; 44:5"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis."},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 25:1-13"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile erit regnum coelórum decem virgínibus: quæ, accipiéntes lámpades suas, exiérunt óbviam sponso et sponsæ. Quinque autem ex eis erant fátuæ, et quinque prudéntes: sed quinque fátuæ, accéptis lampádibus, non sumpsérunt óleum secum: prudéntes vero accepérunt óleum in vasis suis cum lampádibus. Moram autem faciénte sponso, dormitavérunt omnes et dormiérunt. Média autem nocte clamor factus est: Ecce, sponsus venit, exíte óbviam ei. Tunc surrexérunt omnes vírgines illae, et ornavérunt lámpades suas. Fátuæ autem sapiéntibus dixérunt: Date nobis de óleo vestro: quia lámpades nostræ exstinguúntur. Respondérunt prudéntes, dicéntes: Ne forte non suffíciat nobis et vobis, ite pótius ad vendéntes, et émite vobis. Dum autem irent émere, venit sponsus: et quæ parátæ erant, intravérunt cum eo ad núptias, et clausa est jánua. Novíssime vero véniunt et réliquæ vírgines, dicéntes: Dómine, Dómine, áperi nobis. At ille respóndens, ait: Amen, dico vobis, néscio vos. Vigiláte ítaque, quia nescítis diem neque horam."}],"Offertorium":[{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Afferéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia et exsultatióne: adducéntur in templum Regi Dómino. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Hæc hóstia, Dómine, placatiónis et laudis, quǽsumus: ut, intercedénte beáta Cæcília Vírgine et Mártyre tua, nos propitiatióne tua dignos semper effíciat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 118:78; 118:80"},{"k":"text","la":"Confundántur supérbi, quia injúste iniquitátem fecérunt in me: ego autem in mandátis tuis exercébor, in tuis justificatiónibus, ut non confúndar. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Satiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"9a69c43b9af18214":{"t":"Ps 118, 46-47, Ps 118, 1\n(Ps 118, 46-47) Govorio sam pred kraljevima o tvojim odredbama i nisam se smeo, i razmišljao sam o tvojim zapovijedima koje veoma ljubim. (Ps 118, 1) Blago onima koji idu neokaljanim putem, koji žive po zakonu Gospodnjemu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 118, 46-47) Govorio sam pred kraljevima o tvojim odredbama i nisam se smeo, i razmišljao sam o tvojim zapovijedima koje veoma ljubim."},"0f3441e45178c247":{"t":"<i>Pomolimo se</i>.\nBože, koji nas razveseljuješ godišnjom svetkovinom blažene Cecilije djevice i mučenice svoje, daj da nju, koju slavimo bogoslužjem, nasljedujemo primjerom pobožnog života.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji nae razveseljuješ obljetnom slavom blažene djevice i mučenice Cecilije, daj, da nasljedujemo primjerom 'bogoljubnoga života onu, koju službom štujemo, po Gospodinu . . .","knRef":"Kniewald 1942, str. 782–783 (snimka 392) (OCR)"},"68b7d4adafa31fe1":{"t":"Sir 51, 13-17\nČitanje knjige Mudrosti. Bože Gospodaru moj, uzdigao si me s mojeg prebivališta na zemlji, a ja sam molila da me mine smrt koja me zarobila. Zazvala sam Gospodina, Oca moga Gospodara, da me u vrijeme oholica ne ostavi bez pomoći na dan mojih muka. Hvalit ću te bez prestanka i slavit ću te priznavanjem, jer si uslišao moju molitvu. Izbavio si me od propasti i spasio u vrijeme nepravde. Zato ću te slaviti i hvaliti, Gospodine Bože naš.","kn":"Čitanje Knjige mudrosti (Crkv. 51, 13-17); Gospodine Bože -moj, uzdigao si moje prebivalište sa zemlje, a ja sam molila, da me mine smrt, koja se bacila na me. Zazvala sam Gospođina, Oca mojeg« Gospodina, da me ne ostavi u dan mojih muka i bez pomoći u vrijeme o-holica. Hvallt ću te neprestano i slavit ću te s priznavanjem, jer je uslišana moja molitva, izbavio si me od propasti i spasio u vrijeme nepravde. Zato ću te slaviti i hvaliti, Gospodine, Bože naš.","knRef":"Kniewald 1942, str. 822–823 (snimka 412) (OCR)"},"b43d09a184f1d656":{"t":"Ps 44, 11 i 12, Ps 44, 5\n(Ps 44, 11 i 12) Čuj, kćeri, i pogledaj i prikloni svoje uho, jer je Kralj zavolio tvoju ljepotu. (Ps 44, 5) U svojoj veličanstvenoj ljepoti sretno pođi, napreduj i kraljuj.\n\nMt 25, 4 i 6\n<i>Aleluja</i>, <i>aleluja</i>.\nPet je mudrih djevica uzelo ulje u svojim posudama zajedno sa svjetiljkama. A o ponoći začu se vika: Evo dolazi zaručnik, iziđite ususret Kristu Gospodinu, <i>aleluja</i>.","v":"ista misa na staroj stranici, latinski tekst odstupa (sličnost 0.95)","kn":"(Ps. 44, 11). Slušaj, kćeri, i gledaj i prigni uho svoje! Jer omilje kralju ljepota tvoja. Ljepotom svojom i krasotom svojom pohitaj, pođi sretno i kraljuj.\nAleluja, aleluja. (Mat. 25, 4). Pet mudrih djevica uzeše ulja u sudovima svojim sa žišcima. A u ponoći stade vika: Eto ženika, gdje ide, iziđite u susret Kristu Gospodinu. Aleluja.","knRef":"Kniewald 1942, str. 783"},"04a5e5f3be261c56":{"t":"Mt 25, 1-13\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Kraljevstvo je nebesko kao deset djevica, koje uzeše svoje svjetiljke i iziđoše u susret zaručniku i zaručnici. Pet ih je bilo ludih, a pet mudrih. Pet ludih uzeše svjetiljke, a ne uzeše sa sobom ulja, a mudre sa svjetiljkama uzeše ulja u svojim posudama. Ali jer se zaručnik zabavio, sve zadrijemaše i zaspaše. A o ponoći nasta vika: Evo, ide zaručnik, iziđite mu u susret! Tada ustaše sve djevice i zapališe svoje svjetiljke. Lude tada reknu mudrima: Dajte nam od svoga ulja, jer se gase naše svjetiljke. Mudre odgovore: Da ne bi ponestalo nama i vama, idite radije do prodavača i kupite. Dok su išle kupovati, dođe zaručnik, i koje su bile spremne, uđu s njim na svadbu i zatvore se vrata. Napokon dođu i ostale djevice i reknu: Gospodine, Gospodine, otvori nam! On im odgovori: Zaista vam kažem: Ne poznam vas. Bdijte dakle, jer ne znate ni dana ni časa.","kn":"t Slijedi sv. evanđelje po Mateju (25, 1-13). U ono vrijeme reče Isus svojim učenicima ovu prispodobu: Kraljevstvo je nebesko kao deset djevica, koje uzeše svoje svjetiljke 1 iziđoše ususret zaručniku i zaručnici. Pet ih je bilo ludih, a pet mudrih. Pet ludih uzeše svjetiljke, a ne uzeše sa sobom ulja, a mudre sa svjetiljkama uzeše ulja u svojim posudama. Ali jer se zaručnik zabavio, sve zadrijemaše i zaspaše. A o ponoći nasta vika; Evo, ide zaručnik, iziđite mu ususret! Tada ustadoše sve djevice i zapališe svoje svjetUjke. Lude tada reknu mudrima: Dajte nam od svoga ulja, jer se gase naše svjetiljke. Mudre odgovore: Da ne bi ponestalo nama i vama, idite radije do prodavača i kupite. Dok su išle kupovati, dođe zaručnik, i koje'su bile spremne, uniđu s njim na svadbu i zatvore se vrata. Napokon dođu i ostale djevice i reknu: Gospodine, Gospodine, otvori nam! On im odgovori: Zaista vam kažem: Ne poznam vas. Bdijte, dakle, jer ne znate ni dana ni časa!","knRef":"Kniewald 1942, str. 826–827 (snimka 414) (OCR)"},"805e908c21018a9c":{"t":"Ps 44, 15-16\nZa njom će poći pred Kralja djevice. Drugarice će njezine poći k tebi u radosti, poći će u hram Kralja Gospodina.","kn":"(Ps. 44, 15, 16). Prate je djevice i vode je kralju; u radosti i veselju vode je u hram Kralja, Gosipodina.","knRef":"Kniewald 1942, str. 822–823 (snimka 412) (OCR)"},"047209ff0cbbcc37":{"t":"Molimo, Gospodine, da nas ova žrtva pomirenja i hvale po zagovoru blažene Cecilije djevice i mučenice tvoje učini uvijek dostojnima tvoga oproštenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ova nas žrtva pomirenja i hvale, molimo. Gospodine, zagovorom blažene Cecilije, Tvoje mučenice i djevice, učinila dostojnima Tvoga pomirenja, po G. n.","knRef":"Kniewald 1942, str. 782–783 (snimka 392) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"80190e9b2b2437df":{"t":"Ps 118, 78 i 80\nNeka se postide oholi, jer me zlostavljaju bez razloga. A ja ispunjam zapovijedi tvoje i naloge tvoje da ne moram nečasno propasti."},"dfce8e9a1c23b4e0":{"t":"<i>Pomolimo se</i>.\nNasitio si, Gospodine, svoju obitelj svetim darovima, molimo da nas uvijek krijepiš na zagovor one čiju svečanost slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, pošto si nahranio svoju obitelj presvetim darovima, da nas uvijek krijepiš zagovorom one, koje blagdan slavimo, Po G. n.","knRef":"Kniewald 1942, str. 506–507 (snimka 254) (OCR)"}}});
